<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class UpbringingWorkflowController extends Controller{
private function base(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('head_academic')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('curator')||$r->user()->hasRole('psychologist')||$r->user()->hasRole('social_teacher'),403);}
private function specialist(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('psychologist')||$r->user()->hasRole('social_teacher'),403);}
public function plans(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$rows=DB::table('curator_plans as p')->join('study_groups as g','g.id','=','p.study_group_id')->where('p.academic_period_id',$p->id)->select('p.*','g.name as group_name')->get();return view('upbringing.plans',compact('groups','rows'));}
public function planStore(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','title'=>'required|string|max:255','goals'=>'nullable|string|max:5000']);DB::table('curator_plans')->updateOrInsert(['academic_period_id'=>$p->id,'study_group_id'=>$d['study_group_id']],['title'=>$d['title'],'goals'=>$d['goals']??null,'curator_user_id'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function planUpdate(Request $r,$id){$this->base($r);$x=DB::table('curator_plans')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['title'=>'required|string|max:255','goals'=>'nullable|string|max:5000']);DB::table('curator_plans')->where('id',$id)->update($d+['updated_at'=>now()]);return back();}
public function planArchive(Request $r,$id){$this->base($r);$x=DB::table('curator_plans')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);DB::table('curator_plans')->where('id',$id)->update(['archived_at'=>now(),'updated_at'=>now()]);return back();}
public function planItem(Request $r,$plan){$this->base($r);$x=DB::table('curator_plans')->find($plan);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['planned_on'=>'nullable|date','direction'=>'required|string|max:100','title'=>'required|string|max:500']);DB::table('curator_plan_items')->insert($d+['curator_plan_id'=>$plan,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function meetings(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$rows=DB::table('parent_meetings as m')->join('study_groups as g','g.id','=','m.study_group_id')->where('m.academic_period_id',$p->id)->select('m.*','g.name as group_name')->orderByDesc('m.meeting_at')->get();return view('upbringing.meetings',compact('groups','rows'));}
public function meetingStore(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','meeting_at'=>'required|date','topic'=>'required|string|max:500','agenda'=>'nullable|string|max:5000','attendees_count'=>'nullable|integer|min:0','decisions'=>'nullable|string|max:5000','protocol_number'=>'nullable|string|max:100']);DB::table('parent_meetings')->insert($d+['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function meetingUpdate(Request $r,$id){$this->base($r);$x=DB::table('parent_meetings')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['meeting_at'=>'required|date','topic'=>'required|string|max:500','agenda'=>'nullable|string|max:5000','attendees_count'=>'nullable|integer|min:0','decisions'=>'nullable|string|max:5000','protocol_number'=>'nullable|string|max:100']);DB::table('parent_meetings')->where('id',$id)->update($d+['updated_at'=>now()]);return back();}
public function meetingArchive(Request $r,$id){$this->base($r);$x=DB::table('parent_meetings')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);DB::table('parent_meetings')->where('id',$id)->update(['archived_at'=>now(),'updated_at'=>now()]);return back();}
public function appeals(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');$students=DB::table('students as s')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->where('s.status','active')->select('s.id','s.last_name','s.first_name','g.name as group_name')->orderBy('s.last_name')->get();$rows=DB::table('upbringing_appeals')->where('academic_period_id',$p->id)->orderByRaw("case when status='new' then 0 else 1 end")->orderByDesc('created_at')->get();return view('upbringing.appeals',compact('rows','students'));}
public function appealStore(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['source_type'=>'required|in:student,parent,teacher,employee,other','student_id'=>'nullable|exists:students,id','contact_name'=>'nullable|string|max:255','contact'=>'nullable|string|max:255','category'=>'required|string|max:100','message'=>'required|string|max:5000']);DB::table('upbringing_appeals')->insert($d+['academic_period_id'=>$p->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function appealResolve(Request $r,$id){$this->base($r);$x=DB::table('upbringing_appeals')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['resolution'=>'required|string|max:5000']);DB::table('upbringing_appeals')->where('id',$id)->update(['status'=>'closed','resolution'=>$d['resolution'],'assigned_user_id'=>$r->user()->id,'closed_at'=>now(),'updated_at'=>now()]);return back();}
public function specialists(Request $r){$this->specialist($r);$p=$r->attributes->get('academic_period');$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();$rows=DB::table('specialist_consultations as c')->join('students as s','s.id','=','c.student_id')->where('c.academic_period_id',$p->id)->select('c.*','s.last_name','s.first_name')->orderByDesc('c.consulted_at')->get();return view('upbringing.specialists',compact('students','rows'));}
public function specialistStore(Request $r){$this->specialist($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['student_id'=>'required|exists:students,id','specialist_type'=>'required|in:psychologist,social_teacher','consulted_at'=>'required|date','topic'=>'nullable|string|max:500','confidential_note'=>'nullable|string|max:10000','shared_recommendation'=>'nullable|string|max:5000','follow_up_on'=>'nullable|date']);DB::table('specialist_consultations')->insert($d+['academic_period_id'=>$p->id,'specialist_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function report(Request $r){$this->base($r);$p=$r->attributes->get('academic_period');$from=$r->date('from')?:$p->starts_on;$to=$r->date('to')?:$p->ends_on;$stats=['events'=>DB::table('upbringing_events')->where('academic_period_id',$p->id)->whereBetween('starts_at',[$from,$to.' 23:59:59'])->count(),'completed'=>DB::table('upbringing_events')->where('academic_period_id',$p->id)->where('status','completed')->whereBetween('starts_at',[$from,$to.' 23:59:59'])->count(),'cases_opened'=>DB::table('student_support_cases')->where('academic_period_id',$p->id)->whereBetween('created_at',[$from,$to.' 23:59:59'])->count(),'achievements'=>DB::table('student_achievements')->where('academic_period_id',$p->id)->whereBetween('achieved_on',[$from,$to])->count(),'meetings'=>DB::table('parent_meetings')->where('academic_period_id',$p->id)->whereBetween('meeting_at',[$from,$to.' 23:59:59'])->count(),'appeals'=>DB::table('upbringing_appeals')->where('academic_period_id',$p->id)->whereBetween('created_at',[$from,$to.' 23:59:59'])->count()];return view('upbringing.report',compact('stats','from','to'));}
}